import{_ as t,o,c as a,a3 as r}from"./chunks/framework.B0LNVsFV.js";const d="/contract-mgmt-docs/assets/05-login.Dk_hx-4x.png",g=JSON.parse('{"title":"5. Login","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/05-login.md","filePath":"chapters/05-login.md"}'),n={name:"chapters/05-login.md"};function i(l,e,s,c,h,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_5-login" tabindex="-1">5. Login <a class="header-anchor" href="#_5-login" aria-label="Permalink to &quot;5. Login&quot;">​</a></h1><h2 id="read" tabindex="-1">Read <a class="header-anchor" href="#read" aria-label="Permalink to &quot;Read&quot;">​</a></h2><ul><li><a href="https://github.com/manfredsteyer/angular-oauth2-oidc" target="_blank" rel="noreferrer">Angular OAuth2 OIDC</a></li><li><a href="https://angular.dev/guide/http/interceptors" target="_blank" rel="noreferrer">Angular Interceptor</a></li><li><a href="https://angular.dev/guide/routing/route-guards" target="_blank" rel="noreferrer">Angular Guard</a></li><li><a href="https://angular.dev/reference/migrations/standalone" target="_blank" rel="noreferrer">Angular Standalone</a></li><li><a href="https://angular.dev/reference/migrations/inject-function" target="_blank" rel="noreferrer">Angular Inject</a></li><li><a href="https://angular.dev/ecosystem/rxjs-interop/take-until-destroyed" target="_blank" rel="noreferrer">Angular TakeUntilDestroyed</a></li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Install the OAuth2/OIDC library. The major version must match Angular:</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm i angular-oauth2-oidc@21 --legacy-peer-deps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>The values for <code>angular-oauth2-oidc</code> and <code>app.config.json</code> (local setup, Keycloak seeded in chapter 1). The property names are the ones of the library&#39;s <code>AuthConfig</code>, so the file can be passed to the library as it is:</li></ol><table tabindex="0"><thead><tr><th>Setting</th><th>Local value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>issuer</code></td><td><code>http://localhost:8081/realms/contract-mgmt</code></td><td>Keycloak base URL plus realm. The library derives the discovery document from it: <code>&lt;issuer&gt;/.well-known/openid-configuration</code></td></tr><tr><td><code>clientId</code></td><td><code>contract-mgmt-frontend</code></td><td>Public client created by the Keycloak seed</td></tr><tr><td><code>responseType</code></td><td><code>code</code></td><td>Authorization code flow. PKCE is used automatically with it</td></tr><tr><td><code>scope</code></td><td><code>openid profile</code></td><td><code>openid</code> makes it an OIDC login, <code>profile</code> adds the username to the token</td></tr><tr><td><code>redirectUri</code></td><td><code>http://localhost:4200/</code></td><td>Where Keycloak sends the user back after login: the app itself. The seeded client allows <code>http://localhost:4200/*</code></td></tr><tr><td><code>postLogoutRedirectUri</code></td><td><code>http://localhost:4200/</code></td><td>Where Keycloak sends the user back after logout</td></tr><tr><td><code>requireHttps</code></td><td><code>false</code></td><td>Allows <code>http</code> for local development. Must be <code>true</code> in production</td></tr><tr><td><code>showDebugInformation</code></td><td><code>false</code></td><td>Set to <code>true</code> to see the library&#39;s login steps in the browser console</td></tr></tbody></table><p>Taken from the discovery document, not configured by hand:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>URL</th></tr></thead><tbody><tr><td>Authorization</td><td><code>&lt;issuer&gt;/protocol/openid-connect/auth</code></td></tr><tr><td>Token</td><td><code>&lt;issuer&gt;/protocol/openid-connect/token</code></td></tr><tr><td>Logout</td><td><code>&lt;issuer&gt;/protocol/openid-connect/logout</code></td></tr><tr><td>JWKS (signing keys)</td><td><code>&lt;issuer&gt;/protocol/openid-connect/certs</code></td></tr></tbody></table><p>Read from the access token by the auth service:</p><table tabindex="0"><thead><tr><th>Information</th><th>Claim</th></tr></thead><tbody><tr><td>Username</td><td><code>preferred_username</code></td></tr><tr><td>Roles</td><td><code>realm_access.roles</code> (<code>broker</code>, <code>superadmin</code>)</td></tr></tbody></table><ol start="3"><li>Implement:</li></ol><table tabindex="0"><thead><tr><th>What</th><th>Business description</th></tr></thead><tbody><tr><td>Runtime configuration file</td><td><code>public/app.config.json</code> holds the authorization settings: issuer (Keycloak base URL plus realm), client id, scope, redirect path, post-logout redirect path and whether HTTPS is required (off for local development). Nothing of this is hard-coded in the code or the build</td></tr><tr><td>Config loading</td><td>The file is fetched before the app is bootstrapped. Only after it is loaded the app starts, with the settings available to the whole app. If the file cannot be loaded, show a clear error instead of starting</td></tr><tr><td>Library setup</td><td>Register <code>angular-oauth2-oidc</code> for the whole app. Configure it from the loaded settings with the authorization code flow (PKCE is used with it), client <code>contract-mgmt-frontend</code>, the JWKS validation handler to verify token signatures, and <code>localStorage</code> as the token storage</td></tr><tr><td>Discovery</td><td>The endpoints (authorization, token, logout and the JWKS keys) are not configured by hand: the library loads them from the discovery document of the issuer</td></tr><tr><td>Startup</td><td>After the config is loaded, the app loads the discovery document and lets the library finish a login if Keycloak has just redirected back with a code. The redirect target is the app itself, so no callback page is needed. After a successful login the user lands on the contract list</td></tr><tr><td>Token refresh</td><td>The library renews the access token automatically before it expires</td></tr><tr><td>Auth service</td><td>A thin service around the library: whether the user is logged in (as a signal), username, roles read from the access token, login, logout</td></tr><tr><td>Login page</td><td>A page with one button that starts the login</td></tr><tr><td>Logout</td><td>Calls the library&#39;s <code>logOut()</code> method (no hand-written token removal or redirect). The library clears the stored tokens and sends the user to the Keycloak logout endpoint, using the post-logout redirect URI from the settings, so the Keycloak session ends too</td></tr><tr><td>Interceptor</td><td>Adds the access token to every BFF request, but not to other requests. When the BFF answers 401 the user goes to the login page</td></tr><tr><td>Route protection</td><td>Anonymous users are sent to the login page. A second guard restricts routes to one role and sends other users to the contract list</td></tr><tr><td>Role directive</td><td>Shows an element only for users with a given role (for example superadmin)</td></tr><tr><td>Header</td><td>When logged in: link to contracts, username, the language switch from the i18n chapter and logout</td></tr></tbody></table><ol start="4"><li>Change a value in <code>app.config.json</code> (for example the client id), reload without rebuilding, and see that the login uses it.</li><li>Log in as <code>broker</code> and as <code>admin</code> and compare the roles you see.</li></ol><h2 id="visual-mockup" tabindex="-1">Visual mockup <a class="header-anchor" href="#visual-mockup" aria-label="Permalink to &quot;Visual mockup&quot;">​</a></h2><p><img src="'+d+'" alt="Login card with a primary log in button"></p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li>The config is loaded from the file before the app starts, and a missing file gives an error</li><li>The auth service reports logged in, username and roles from an access token (the library is replaced by a stub)</li><li>The auth service reports logged out when the library has no valid token</li><li>The auth service logout calls <code>logOut()</code> of the library</li><li>The interceptor adds the token to BFF requests only</li><li>A 401 answer goes to the login page</li><li>The directive hides an element for a broker and shows it for a superadmin</li><li>The header is hidden when logged out and shows the username when logged in</li></ul><p>Done when the Keycloak settings come only from <code>app.config.json</code>, anonymous users cannot reach the app, login and logout work through angular-oauth2-oidc, and the tests are green.</p><h2 id="what-you-will-see" tabindex="-1">What you will see <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What you will see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>What appears</th></tr></thead><tbody><tr><td>Open <code>http://localhost:4200</code> logged out</td><td>The login page: the title and one login button. No header is shown</td></tr><tr><td>Click the login button</td><td>The Keycloak login form. Sign in as <code>broker</code> / <code>broker</code> or <code>admin</code> / <code>admin</code></td></tr><tr><td>After the login</td><td>The homepage (the contract list, still a placeholder in this chapter) with a header: link to contracts, your username, the language switch and a logout button</td></tr><tr><td>Click logout</td><td>The header disappears and you are back on the login page; opening the app again asks for the login</td></tr><tr><td>Open the app as <code>admin</code> and as <code>broker</code></td><td>The same page and header with a different username; the roles differ (the admin link for superadmins follows in the admin chapter)</td></tr></tbody></table><h2 id="be-able-to-explain" tabindex="-1">Be able to explain <a class="header-anchor" href="#be-able-to-explain" aria-label="Permalink to &quot;Be able to explain&quot;">​</a></h2><ul><li>OAuth 2.0 Standard Flow (how does it work, including the application flow, token management, etc.)</li></ul>',24)])])}const b=t(n,[["render",i]]);export{g as __pageData,b as default};
